define("mod_aiconcept/student_chat",["core/ajax"],function(Ajax){function addMsg(role,text){var h=document.getElementById("aiconcept-history");if(!h)return;var row=document.createElement("div");row.className="aiconcept-msg "+role;var b=document.createElement("div");b.className="bubble";var r=document.createElement("div");r.className="role";r.innerText=(role==="student"?"You":"Assistant");b.appendChild(r);b.appendChild(document.createTextNode(text));row.appendChild(b);h.appendChild(row);h.scrollTop=h.scrollHeight}
function badge(status){var el=document.querySelector(".aiconcept-progress");if(!el)return;el.className="aiconcept-progress "+status;el.innerText=status.charAt(0).toUpperCase()+status.slice(1)}
return{init:function(cfg){var cmid=parseInt(cfg.cmid||0,10)||0;var submissionid=parseInt(cfg.submissionid||0,10)||0;var ta=document.getElementById("aiconcept-code");var btn=document.getElementById("aiconcept-submit");var clr=document.getElementById("aiconcept-clear");var taf=document.getElementById("aiconcept-final");var btnf=document.getElementById("aiconcept-final-submit");
function call(wsargs,onok){Ajax.call([{methodname:"mod_aiconcept_submit_and_respond",args:wsargs}])[0].then(function(res){try{submissionid=parseInt(res.submissionid,10)||submissionid}catch(e){}onok(res)}).catch(function(err){addMsg("assistant","Error: "+(err&&err.message?err.message:JSON.stringify(err)))})}
function loadHistory(){ if(!submissionid) return; Ajax.call([{methodname:"mod_aiconcept_fetch_turns",args:{submissionid:submissionid}}])[0].then(function(list){document.getElementById("aiconcept-history").innerHTML="";list.forEach(function(t){addMsg(t.role,t.content)})}).catch(function(){})}
function submitNow(){var code=(ta.value||"").trim();if(!code){ta.focus();return}addMsg("student",code);btn.disabled=!0;call({cmid:cmid,submissionid:submissionid,studentcode:code},function(res){addMsg("assistant",res.assistant||"[no content]");btn.disabled=!1;ta.value=""})}
function submitFinal(){var code=(taf.value||"").trim();if(!code){taf.focus();return}if(!submissionid){addMsg("assistant","Start a conversation first, then submit final code.");return}
call({cmid:cmid,submissionid:submissionid,studentcode:"FINAL_SUBMISSION:\n"+code},function(res){addMsg("student","[Final submitted]\n"+code);addMsg("assistant",res.assistant||"[no content]");badge("submitted")})}
if(btn)btn.addEventListener("click",submitNow); if(clr)clr.addEventListener("click",function(){ta.value=""}); if(btnf)btnf.addEventListener("click",submitFinal);
loadHistory();}}});
